public class Test {
    public static void main(String[] a) {
        LookupCache c = new LookupCache(k -> k + "!");
        String[] r = new String[2];
        String miss = capture(() -> r[0] = c.get("alpha"));
        String hit = capture(() -> r[1] = c.get("alpha"));
        if (!(miss.contains("Cache miss: alpha"))) throw new AssertionError("miss not logged");
        if (!(!hit.contains("Cache miss"))) throw new AssertionError("hit was logged as a miss");
        if (!("alpha!".equals(r[0]) && "alpha!".equals(r[1]))) throw new AssertionError("behavior changed");
        System.out.println("PASS");
    }

    static String capture(Runnable r) {
        java.io.PrintStream original = System.out;
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        System.setOut(new java.io.PrintStream(buf, true));
        try { r.run(); } finally { System.setOut(original); }
        return buf.toString();
    }
}
